<style lang="scss" src="./menu.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { MountingPortal, Portal } from "portal-vue";
import {
  destroyModalRootContent,
  ensureModalRoot
} from "../../util/ensure-modal-root";
import { has } from "../../util/has";
import { MenuMode, MenuModeValues } from "./menu.constants";
import Icon from "../../components/icon/icon";
import { IconShape } from "../icon/icon.constants";
import ListView from "../../components/list-view/list-view";
import { hasChild } from "../../util/has-child";
import { OptionMode } from "../selection-menu/selection-menu.constants";

const modeToIconColor = {
  [OptionMode.PRIMARY]: "#ffffff",
  [OptionMode.SECONDARY]: "#2356F6"
};

/**
 * This is a generic Menu for handling showing an overlaid menu that aligns
 * itself relative to an element on the screen. This includes dropdown menus or
 * context menus or other element aligned type items that breaks away from the
 * DOM structure to 'float' in place.
 *
 * This provides a means of displaying rows, sections of rows, rows with a
 * header or even a search element for the header.
 */
@Component({
  components: {
    MountingPortal,
    Icon,
    ListView,
    Portal
  }
})
export default class Menu extends Vue {
  /**
   * When this is provided, it will open the menu relative to these provided
   * bounds.
   *
   * Note: Unless coverBounds is true, these bounds represent where the menu
   * should appear AROUND. Thus, these bounds would be the bounds of something
   * like a selection menu input.
   */
  @Prop({
    type: Object,
    default: () => ({ left: 0, top: 0, width: 100, height: 100 })
  })
  bounds;
  /**
   * Because of the nature of this component, using a portal breaks the normal
   * Vue pattern of handing class names to the top level component. So instead,
   * use this prop
   */
  @Prop({ type: String }) className;
  /**
   * If there is already a modal root in the document, you can specify one here.
   * Otherwise, one will automatically be made
   */
  @Prop({ type: Object }) customModalRoot;
  /**
   * This makes the top row cover the provided bounds IFF the dropdown can fit
   * dropping down
   */
  @Prop({ type: Boolean, default: false }) coverBounds;
  /**
   * Renders a loading graphic when elements for the menu are loading
   */
  @Prop({ type: Boolean, default: false }) isLoading;
  /** Optional height of the rows rendered */
  @Prop({ type: Number, default: 52 }) rowHeight;
  /**
   * Optional height metrics to define the calculated size of the menu. You
   * would implement this if you had customized styling over all of the
   * elements.
   */
  @Prop({
    type: Object,
    default: () => ({
      section: 11,
      header: 58,
      search: 30,
      padding: 0
    })
  })
  heightMetrics;
  /**
   * When true, provides the search bar for the menu and makes the callback
   * active
   */
  @Prop({ type: Boolean, default: true }) search;
  /** When search is true, this is the placeholder for the search input */
  @Prop({ type: String }) searchPlaceholder;
  /**
   * Only if a header is provided, this will produce a close icon for the menu
   */
  @Prop({ type: Boolean, default: false }) closeable;
  /** If provided, this limits how many rows can be displayed at once */
  @Prop({ type: Number, default: 5 }) maxRows;
  /** When provided this sets a manual width for the menu */
  @Prop({ type: Number }) width;
  /** When provided, the menu will scroll to the provided position once */
  @Prop({ type: Number }) scrollToOnce;
  /** Menu render mode to select */
  @Prop({
    type: String,
    default: MenuMode.NORMAL,
    validator: has(MenuModeValues)
  })
  mode;

  @Prop({
    type: Function
  })
  onClear;

  @Prop({
    type: Function
  })
  onSearch;

  @Prop({ type: String }) title;
  @Prop({ type: String }) summary;

  @Prop({
    type: Array,
    required: true
  })
  rows;

  @Prop({
    type: Boolean,
    default: false
  })
  forceDisplayBelow;

  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;
  /** Used to dictate the calculated width of the menu */
  dropdownWidth = null;
  IconShape = IconShape;
  searchValue = "";

  getMenuIconColor(mode) {
    if (mode) {
      return modeToIconColor[mode];
    }

    return "#2356f6";
  }

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu", "__dropdown_modal_root__");
    this.modalRoot = ensureModalRoot("__dropdown_modal_root__");

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }
  }

  mounted() {
    document.addEventListener("mousedown", this.handleDocumentDown);
    document.addEventListener("touchstart", this.handleDocumentDown);
    document.addEventListener("wheel", this.handleDocumentDown, {
      passive: false
    });
  }

  beforeDestroy() {
    this.clearListeners();
  }

  clearListeners() {
    document.removeEventListener("mousedown", this.handleDocumentDown);
    document.removeEventListener("touchstart", this.handleDocumentDown);
    document.removeEventListener("wheel", this.handleDocumentDown);
  }

  willUpdate() {
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }
  }

  updated() {
    if (!this.$refs.container) return;

    if (!this.dropdownWidth) {
      this.dropdownWidth = this.$refs.container.getBoundingClientRect().width;
    }
  }

  calculateHeight(children) {
    if (!children) return 0;

    const rows = this.rows || [];
    const { rowHeight = 30, search, maxRows, heightMetrics = {} } = this;
    const {
      section: sectionHeight = 0,
      header: headerHeight = 58,
      search: searchHeight = 30,
      contentMargin = 0
    } = heightMetrics;

    let height = 0;
    let rowCount = 0;

    // Add in section height
    height += sectionHeight;
    height += contentMargin * 2;

    rowCount = rows.length || 0;

    if (maxRows !== void 0 && maxRows > 0) {
      height += Math.min(maxRows, rowCount) * rowHeight;
    } else {
      height += rowCount * rowHeight;
    }

    if (this.title) {
      height += headerHeight;
    }

    if (search) {
      height += searchHeight;
    }

    return height;
  }

  handleClearClick(e) {
    /**
     * Emits a clear event when the user clicks the clear search button
     *
     * @event clear
     */
    this.$emit("clear");

    e.stopPropagation();
    e.stopImmediatePropagation();
    e.preventDefault();
  }

  handleSearchChange() {
    if (!this.$refs.search) return;
    this.searchValue = this.$refs.search.value;
    /**
     * Emits a search event when the value in the search bar changes
     * @event search
     */
    this.$emit("search", this.searchValue);
  }

  handleDocumentDown(e) {
    // This helps some cases where the menu is long gone but the event persists.
    // This is mostly with bugs in storybook that needs this hand holding.
    if (!hasChild(document, this.$refs.container)) {
      this.clearListeners();
    }

    // Test to see if the target is a child of this menu. If not, this menu is
    // closed. If yes, we let the event proceed naturally.
    if (hasChild(this.$refs.container, e.target)) return;
    e.stopPropagation();
    e.stopImmediatePropagation();
    e.preventDefault();

    /**
     * Emits a close event when the menu detects an interaction that warrants
     * dismissing the menu
     *
     * @event close
     */
    this.$emit("close", e.target);
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get style() {
    let {
      bounds,
      customModalRoot = this.modalRoot,
      coverBounds,
      width: manualWidth,
      heightMetrics = {},
      dropdownWidth,
      forceDisplayBelow
    } = this;

    if (!dropdownWidth && this.$refs.container) {
      dropdownWidth = this.$refs.container.getBoundingClientRect().width;
    }

    if (!dropdownWidth) {
      dropdownWidth = manualWidth || bounds.width;
    }

    const { padding = 0 } = heightMetrics;
    const children = Object.assign({}, this.$children);

    if (bounds) {
      if (!customModalRoot) {
        setTimeout(() => this.forceUpdate(), 200);
        return null;
      }

      bounds.bottom = bounds.top + bounds.height;

      let width = Math.max(manualWidth || 0, bounds.width) || dropdownWidth;
      const totalHeight = this.calculateHeight(children);

      const checkWidth = dropdownWidth || 0;
      const dropdownHeight = Math.min(totalHeight, window.innerHeight);

      const isDown = forceDisplayBelow
        ? true
        : window.innerHeight -
            bounds.bottom +
            (coverBounds ? bounds.height : 0) >
          totalHeight;
      const isUp =
        !isDown && bounds.top + (coverBounds ? bounds.height : 0) > totalHeight;
      const isRight = forceDisplayBelow
        ? false
        : !isDown && !isUp && checkWidth < window.innerWidth - bounds.right;
      const isLeft = forceDisplayBelow
        ? false
        : !isDown && !isUp && !isRight && checkWidth < bounds.left;

      const shiftLeft = (isDown || isUp) && bounds.left > window.innerWidth / 2;

      if (width) {
        width = Math.min(width, window.innerWidth);
      }

      if (coverBounds && !manualWidth) {
        width = Math.min(bounds.width, window.innerWidth);
      }

      const top = isDown
        ? coverBounds
          ? Math.max(bounds.top, 0)
          : Math.max(bounds.bottom + padding, 0)
        : isUp
        ? Math.min(
            bounds.top - dropdownHeight + (coverBounds ? bounds.height : 0),
            window.innerHeight - dropdownHeight
          )
        : 0;

      const left = shiftLeft
        ? bounds.right - checkWidth
        : isRight
        ? bounds.right - (coverBounds ? bounds.width : 0)
        : isLeft
        ? bounds.left - checkWidth + (coverBounds ? bounds.width : 0)
        : bounds.left;

      const viewBox = {
        top: `${top}px`,
        left: `${left}px`,
        width: `${width || 100}px`,
        height: `${dropdownHeight}px`
      };

      return viewBox;
    }

    return {};
  }

  renderRow(h, index, style) {
    const row = (this.rows || [])[index];
    if (!row) return;

    if (row.label) {
      return (
        <div
          key={index}
          class={`Menu__Row ${row.className || ""} Menu--${row.mode}`}
          style={style}
          onClick={() => {
            /**
             * Emits a click event for when a row is selected
             *
             * @event click
             */
            this.$emit("click", row);
          }}
        >
          <div class="Menu__RowLeft">
            {row.icon ? (
              <div class="Menu__OptionIcon">
                <Icon
                  size={20}
                  shape={row.icon}
                  color={this.getMenuIconColor(row.mode)}
                />
              </div>
            ) : (
              ""
            )}
            <span>{row.label}</span>
          </div>
          <div class="Menu__RowRight">
            {row.favourite === true ? (
              <Icon size={22} shape={IconShape.STAR_FULL} color={"#57bfa1"} />
            ) : row.favourite === false ? (
              <Icon size={22} shape={IconShape.STAR_EMPTY} color={"#57bfa1"} />
            ) : (
              ""
            )}
          </div>
        </div>
      );
    }

    return (
      <div
        key={index}
        class={`Menu__Row ${row.className || ""}`}
        style={style}
        onClick={() => {
          /**
           * Emits a click event for when a row is selected
           *
           * @event click
           */
          this.$emit("click", row);
        }}
      >
        <span>{row}</span>
      </div>
    );
  }

  get totalRows() {
    return this.rows?.length;
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div :class="['Menu', className]" :style="style" ref="container">
      <div v-if="Boolean(title)" class="Menu__Section Menu__SectionHeader">
        <div :class="['Menu__Row', 'Menu--header', 'Menu--no-hover']">
          <div class="Menu__RowLabel">{{ title }}</div>
          <Icon
            v-if="closeable"
            class="Menu__SearchIcon"
            :shape="IconShape.CLOSE"
            :size="12"
            color="#000000"
          />
          <div
            v-if="Boolean(onClear)"
            class="Menu__Clear"
            @click="handleClearClick"
          >
            {{ "Clear all" }}
          </div>
        </div>
      </div>
      <div v-if="search" class="Menu__Search">
        <div class="Menu__SearchContent">
          <Icon
            class="Menu__SearchIcon"
            :shape="IconShape.SEARCH"
            :size="11"
            color="rgba(0, 0, 0, 0.1)"
          />
          <input
            class="Menu__SearchInput"
            :spellCheck="false"
            :autoCorrect="false"
            ref="search"
            type="text"
            placeholder="search"
            @input="handleSearchChange"
          />
        </div>
      </div>
      <div class="Menu__Section">
        <ListView
          key="list"
          class="Menu__ListView"
          :rowSize="rowHeight"
          :total="totalRows"
          :scrollToOnce="scrollToOnce"
          :allowTouchInertia="true"
          @range="
            (startIndex, endIndex, total) =>
              $emit('range', startIndex, endIndex, total)
          "
          :renderMethod="renderRow"
        />
      </div>
    </div>
  </MountingPortal>
</template>
